var ids=["activity--work", "artifacts--code", "artifacts--detail", "artifacts--share", "conversation--approval", "project--work", "projects", "projects--new", "routines--new", "settings-account", "settings-appearance", "settings-billing", "settings-billing--plan", "settings-connections", "settings-devices", "settings-general", "settings-notifications", "settings-shortcuts", "settings-voice", "signin"];var n=0;function walk(l){if(l.name.indexOf('link:')===0){var v=l.name.replace(/ \d+$/,'');if(v!==l.name){l.name=v;n++;}}(l.layers||[]).forEach(walk);}['Light','Dark'].forEach(ap=>{var p=H.page('Proto iOS '+ap);ids.forEach(id=>walk(p.layers.find(l=>l.name==='Screen/ios/'+ap+'/Clean/'+id)));});console.log(JSON.stringify({normalized:n}));